  ($str$variable$str$, 'USA', $str$2026-CastInvest$str$, $str$waxPatternToolingConstructionMultiplier$str$, $str$0$str$, NULL, $str$An additional multiplying factor for the wax pattern tooling cost. This accounts for the additional cost of machining the core and cavity features into the mold bases. Default assumption is that machining is done to plates and not into press-fit inserts.$str$, $jsonb${"Variable Name":"waxPatternToolingConstructionMultiplier","String Value":0,"Unit Type Name":null,"Notes":"An additional multiplying factor for the wax pattern tooling cost. This accounts for the additional cost of machining the core and cavity features into the mold bases. Default assumption is that machining is done to plates and not into press-fit inserts."}$jsonb$::jsonb),
